traces.query:
PREFIX net: <http://example.org/network#>
SELECT ?alarm ?label WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice net:Firewall_Edge ;
         rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(?alarm) AS ?criticalCount)
WHERE {
  ?alarm a net:Alarm ;
         net:hasSeverity "CRITICAL" .
}

PREFIX net: <http://example.org/network#>
SELECT ?alarm ?label
WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice net:Router_Core ;
         rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>
SELECT ?severity WHERE {
  net:Alarm_PacketDrop net:hasSeverity ?severity .
}

PREFIX net: <http://example.org/network#>
SELECT ?device (COUNT(?alarm) AS ?alarmCount)
WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice ?device .
}
GROUP BY ?device
ORDER BY DESC(?alarmCount)
LIMIT 1

PREFIX net: <http://example.org/network#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?alarm ?time
WHERE {
  ?alarm a net:Alarm ;
         net:triggeredAt ?time .
}
ORDER BY ?time
LIMIT 1

PREFIX net: <http://example.org/network#>
SELECT ?mitreId WHERE {
  net:Incident_DDoS net:classifiedAs ?ap .
  ?ap net:mitreId ?mitreId .
}

PREFIX net: <http://example.org/network#>

SELECT ?deviceType
WHERE {
  net:Server_Web net:deviceType ?deviceType .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(?alarm) AS ?alarmCount)
WHERE {
  net:Incident_DDoS net:composedOf ?alarm .
}

PREFIX net: <http://example.org/network#>
SELECT ?alarm WHERE {
  ?alarm a net:Alarm ;
         net:hasSeverity "HIGH" .
}

PREFIX net: <http://example.org/network#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?alarm ?time
WHERE {
  ?alarm a net:Alarm ;
         net:triggeredAt ?time .
  FILTER ( ?time > "2026-06-02T14:01:00"^^xsd:dateTime )
}

PREFIX net: <http://example.org/network#>
SELECT ?rootCauseAlarm WHERE {
  net:Incident_DDoS net:composedOf ?alarm .
  ?alarm (net:causedBy|net:causallyLinkedTo)* ?rootCauseAlarm .
  FILTER NOT EXISTS {
    ?rootCauseAlarm (net:causedBy|net:causallyLinkedTo) ?any .
  }
}

PREFIX net: <http://example.org/network#>
SELECT ?rootCause ?label WHERE {
  ?rootCause net:causallyLinkedTo+ net:Alarm_WebTimeout .
  OPTIONAL { ?rootCause rdfs:label ?label . }
} LIMIT 1

PREFIX net: <http://example.org/network#>

SELECT ?cause WHERE {
  net:Alarm_Latency net:causedBy ?cause .
}

PREFIX net: <http://example.org/network#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?alarm ?label
WHERE {
  net:Alarm_FirewallSpike net:causallyLinkedTo+ ?alarm .
  ?alarm a net:Alarm ;
         rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>

ASK {
  net:Alarm_CPU (net:causallyLinkedTo|net:causedBy)+ net:Alarm_WebTimeout .
}

PREFIX net: <http://example.org/network#>

ASK {
  <http://example.org/network#Alarm_Latency> (net:causallyLinkedTo|^net:causallyLinkedTo)* <http://example.org/network#Alarm_WebTimeout> .
}

PREFIX net: <http://example.org/network#>

SELECT ?rootAlarm ?device
WHERE {
  ?rootAlarm a net:Alarm .
  FILTER NOT EXISTS { ?rootAlarm net:causedBy ?cause . }
  ?rootAlarm net:affectsDevice ?device .
}

PREFIX net: <http://example.org/network#>
SELECT ?relation WHERE {
  VALUES ?a { net:Alarm_Latency net:Alarm_PacketDrop }
  VALUES ?b { net:Alarm_Latency net:Alarm_PacketDrop }
  FILTER(?a != ?b)
  { ?a net:causallyLinkedTo ?b } UNION { ?b net:causallyLinkedTo ?a } UNION
  { ?a net:causedBy ?b } UNION { ?b net:causedBy ?a } .
  BIND(CONCAT(STR(?a), " -> ", STR(?b)) AS ?relation)
} LIMIT 1

PREFIX net: <http://example.org/network#>

SELECT ?alarm ?label WHERE {
  ?alarm net:correlatedWith net:Alarm_PacketDrop .
  FILTER NOT EXISTS { ?alarm net:causallyLinkedTo net:Alarm_PacketDrop }
  ?alarm rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?interventionDevice ?interventionDeviceLabel WHERE {
  # Alarms that affect Router R1
  ?alarm net:affectsDevice net:Router_Core .

  # Find the ultimate cause alarm (no incoming causal link)
  ?rootAlarm (net:causallyLinkedTo)* ?alarm .
  FILTER NOT EXISTS { ?parent net:causallyLinkedTo ?rootAlarm }

  # Device affected by the root cause alarm
  ?rootAlarm net:affectsDevice ?interventionDevice .
  OPTIONAL { ?interventionDevice rdfs:label ?interventionDeviceLabel . }
}

PREFIX net: <http://example.org/network#>
SELECT ?alarm WHERE {
  net:Alarm_FirewallSpike net:causallyLinkedTo+ ?alarm .
}

PREFIX net: <http://example.org/network#>

SELECT ?downstreamAlarm ?type ?severity ?triggeredAt WHERE {
  net:Alarm_CPU net:causallyLinkedTo+ ?downstreamAlarm .
  ?downstreamAlarm net:alarmType ?type ;
                  net:hasSeverity ?severity ;
                  net:triggeredAt ?triggeredAt .
}

PREFIX net: <http://example.org/network#>

SELECT (COUNT(DISTINCT ?downstreamAlarm) AS ?preventedAlarms)
WHERE {
  net:Alarm_PacketDrop net:causallyLinkedTo+ ?downstreamAlarm .
}

PREFIX net: <http://example.org/network#>
SELECT ?remainingAlarm ?type ?severity ?time WHERE {
  # Incident containing the CPU alarm
  net:Incident_DDoS net:composedOf ?cpuAlarm .
  FILTER(?cpuAlarm = net:Alarm_CPU)
  # All alarms in the incident
  net:Incident_DDoS net:composedOf ?remainingAlarm .
  # Exclude the CPU alarm itself
  FILTER(?remainingAlarm != net:Alarm_CPU)
  # Exclude alarms that are downstream of the CPU alarm (causally linked)
  FILTER NOT EXISTS {
    net:Alarm_CPU net:causallyLinkedTo+ ?remainingAlarm .
  }
  OPTIONAL { ?remainingAlarm net:alarmType ?type . }
  OPTIONAL { ?remainingAlarm net:hasSeverity ?severity . }
  OPTIONAL { ?remainingAlarm net:triggeredAt ?time . }
}

PREFIX net: <http://example.org/network#>

ASK {
  net:Alarm_Latency net:causallyLinkedTo net:Alarm_WebTimeout .
}
